import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.gtmkOXzY.js";const b=JSON.parse('{"title":"Commands and admin tools","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/commands.md","filePath":"ms-flightsim/commands.md","lastUpdated":null}'),r={name:"ms-flightsim/commands.md"};function n(s,t,i,c,l,m){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="commands-and-admin-tools" tabindex="-1">Commands and admin tools <a class="header-anchor" href="#commands-and-admin-tools" aria-label="Permalink to &quot;Commands and admin tools&quot;">​</a></h1><p>Players mostly use the tablet and NPCs; admins do nearly everything from <code>/adminps</code>. Admin commands accept anyone with the <code>command</code> ace or a framework group listed in <code>Config.AdminGroups</code> (default <code>admin</code>, <code>superadmin</code>).</p><h2 id="player-commands" tabindex="-1">Player commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/pilottablet</code></td><td>Open the pilot tablet</td></tr><tr><td><code>/myflights</code></td><td>List your recorded flights</td></tr><tr><td><code>/resetpilothud</code></td><td>Reset the HUD layout</td></tr><tr><td><code>/unstuckjobs</code></td><td>Clear a stuck job state</td></tr><tr><td><code>/groundservices</code></td><td>In an aircraft: request ground services. On foot: open the crew board (sign on there)</td></tr><tr><td><code>/gscrew</code></td><td>Open the ground-crew board from anywhere</td></tr><tr><td><code>/msefleet</code></td><td>Ground-vehicle menu</td></tr><tr><td><code>/apheading &lt;deg&gt;</code> · <code>/apalt &lt;ft&gt;</code> · <code>/apmode nav|hdg</code></td><td>Autopilot heading, altitude and mode</td></tr><tr><td><code>/heavylift</code> · <code>/heavyliftcancel</code></td><td>Start or cancel a heavy-lift job</td></tr><tr><td><code>/cancelmedevac</code></td><td>Cancel a medevac</td></tr><tr><td><code>/subco ...</code></td><td>Sub-company actions: create, rename, disband, assign, unassign, fleet, board</td></tr></tbody></table><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p>Players can rebind these in <strong>Settings → Key Bindings → FiveM</strong>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td>F10</td><td>ATC menu and cursor (<code>/atccursor</code> if F10 is taken)</td></tr><tr><td>E</td><td>Interact with NPCs and the ground board; sit at the tower console (that one is rebindable as &quot;ATC console: sit at the screens&quot;)</td></tr><tr><td>B</td><td>Smoke colour (sky writing, airshow)</td></tr><tr><td>P / G / O / H</td><td>Airshow leader: cycle routine, engage, start, disengage</td></tr><tr><td>L</td><td>Belt loader on/off</td></tr><tr><td>Y</td><td>Drop cargo (smuggling; set by <code>Config.Smuggling.dropKey</code>)</td></tr><tr><td><em>(unbound)</em></td><td>Autopilot and autoland toggles — bind them yourself</td></tr></tbody></table><h2 id="admin-commands" tabindex="-1">Admin commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to &quot;Admin commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/adminps</code></td><td>Admin panel (name set by <code>Config.AdminCommand</code>)</td></tr><tr><td><code>/atcscope place|list|remove|calibrate</code></td><td>Place and manage ATC tower consoles</td></tr><tr><td><code>/gsboard place|list|remove</code></td><td>Place and manage ground-service boards</td></tr><tr><td><code>/airportnav</code></td><td>Show an airport&#39;s taxiway network; editing and saving it is admin-only</td></tr><tr><td><code>/aitraffic preset light|medium|heavy</code> · <code>why</code> · <code>here</code></td><td>Tune and diagnose AI traffic (ace <code>msflightsim.admin</code>)</td></tr><tr><td><code>subcodiag</code> <em>(server console)</em></td><td>Check the sub-company database setup</td></tr></tbody></table><h2 id="the-admin-panel" tabindex="-1">The admin panel <a class="header-anchor" href="#the-admin-panel" aria-label="Permalink to &quot;The admin panel&quot;">​</a></h2><p><code>/adminps</code> has these tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>For</th></tr></thead><tbody><tr><td>Players</td><td>Give or revoke licences, reset strikes, blacklist, whitelist pilots</td></tr><tr><td>Zones</td><td>Create and edit altitude and no-fly zones</td></tr><tr><td>Locations</td><td>Enable or disable NPC sites</td></tr><tr><td>Airports</td><td>Add airports or override built-in ones. A disabled airport has no jobs, ATC or AI. <em>Capture Walk</em> records points as you walk</td></tr><tr><td>Screens</td><td>ATC consoles and ground-service boards</td></tr><tr><td>Licensed Pilots</td><td>Every pilot, online and offline</td></tr><tr><td>Aircraft</td><td>The dealer list</td></tr><tr><td>Jobs</td><td>On/off per mission</td></tr><tr><td>Salaries</td><td>Pay presets and the economy gauge</td></tr><tr><td>Settings</td><td>General options</td></tr></tbody></table>',12)])])}const u=d(r,[["render",n]]);export{b as __pageData,u as default};
